<?php
require_once __DIR__ . '/_common.php';
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['update_status'])) {
    $order_id=(int)($_POST['order_id']??0); $status=$_POST['status']??'';
    if($order_id>0 && in_array($status,['confirmed','shipped','delivered'],true)) {
        // Only allow a vendor to update an order that contains one of their items.
        $check=$conn->prepare("SELECT id FROM order_items WHERE order_id=? AND vendor_id=? LIMIT 1");$check->bind_param('ii',$order_id,$vendor_id);$check->execute();
        if($check->get_result()->num_rows){$u=$conn->prepare("UPDATE orders SET status=? WHERE id=? AND status <> 'cancelled'");$u->bind_param('si',$status,$order_id);$u->execute();}
    }
}
$q=$conn->prepare("SELECT o.id,o.total_amount,o.status,o.shipping_address,o.created_at,SUM(oi.quantity) quantity,COUNT(DISTINCT oi.product_id) product_count FROM orders o JOIN order_items oi ON o.id=oi.order_id WHERE oi.vendor_id=? GROUP BY o.id ORDER BY o.created_at DESC");$q->bind_param('i',$vendor_id);$q->execute();$orders=$q->get_result();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders - Bazario Vendor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet"><link href="../assets/css/theme.css" rel="stylesheet"><link href="style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><aside class="col-md-3 col-lg-2 px-0"><div class="sidebar p-3"><h4 class="text-white text-center mb-4"><i class="fas fa-store me-2"></i>Bazario</h4><nav class="nav flex-column"><a class="nav-link" href="dashboard.php">Dashboard</a><a class="nav-link" href="products.php">My Products</a><a class="nav-link" href="add_product.php">Add Product</a><a class="nav-link active" href="orders.php">Orders</a><hr class="text-white-50"><a class="nav-link" href="../store.php">View Store</a><a class="nav-link" href="../logout.php">Logout</a></nav></div></aside><main class="col-md-9 col-lg-10"><div class="p-4"><h2 class="text-white">Store Orders</h2><p class="text-white-50 mb-4">Orders containing your products.</p><div class="glass-card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Items</th><th>Customer address</th><th>Total order</th><th>Status</th><th>Update</th></tr></thead><tbody><?php while($o=$orders->fetch_assoc()):?><tr><td>#<?=$o['id']?><br><small class="text-white-50"><?=htmlspecialchars($o['created_at'])?></small></td><td><?=$o['quantity']?> units / <?=$o['product_count']?> products</td><td><?=htmlspecialchars($o['shipping_address']??'—')?></td><td>₹<?=number_format($o['total_amount'],2)?></td><td><?=htmlspecialchars(ucfirst($o['status']))?></td><td><?php if($o['status']!=='delivered'&&$o['status']!=='cancelled'):?><form method="post" class="d-flex gap-2"><input type="hidden" name="order_id" value="<?=$o['id']?>"><select name="status" class="form-select form-select-sm"><option value="confirmed">Confirmed</option><option value="shipped">Shipped</option><option value="delivered">Delivered</option></select><button name="update_status" class="btn btn-brand btn-sm">Update</button></form><?php else:?><span class="text-white-50">No action</span><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></main></div></div></body></html>
